<?php
declare(strict_types=1);
require_once __DIR__.'/../src/Config.php'; require_once __DIR__.'/../src/Database.php'; require_once __DIR__.'/../src/Security.php'; require_once __DIR__.'/../src/MetaClient.php'; require_once __DIR__.'/../src/Support.php';
use ConectaFlow\{Config,Database,MetaClient}; use function ConectaFlow\db;
Config::load(__DIR__.'/../.env');
$batch=(int)Config::get('QUEUE_BATCH_SIZE',20); $maxRetries=(int)Config::get('QUEUE_MAX_RETRIES',3); $once=isset($argv[1])&&$argv[1]==='--once';
do { $rows=[]; try { Database::transaction(function($pdo)use(&$rows,$batch){$stmt=$pdo->prepare('SELECT q.*,c.message_text,c.category,cc.contact_id,ct.phone,ct.name FROM message_queue q JOIN campaigns c ON c.id=q.campaign_id JOIN campaign_contacts cc ON cc.id=q.campaign_contact_id JOIN contacts ct ON ct.id=cc.contact_id WHERE q.status="pending" AND q.available_at<=NOW() AND c.status IN ("processing","scheduled") ORDER BY q.id LIMIT ? FOR UPDATE SKIP LOCKED');$stmt->bindValue(1,$batch,PDO::PARAM_INT);$stmt->execute();$rows=$stmt->fetchAll(); if($rows){$ids=array_column($rows,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$pdo->prepare("UPDATE message_queue SET status='processing',locked_at=NOW(),attempts=attempts+1 WHERE id IN ($marks)")->execute($ids);}}); }catch(Throwable $e){fwrite(STDERR,$e->getMessage().PHP_EOL);break;}
    foreach($rows as $row){try{$account=db()->prepare('SELECT wa.*,wn.phone_number_id FROM whatsapp_accounts wa JOIN whatsapp_numbers wn ON wn.whatsapp_account_id=wa.id WHERE wa.company_id=? LIMIT 1');$campaign=db()->prepare('SELECT company_id FROM campaigns WHERE id=?');$campaign->execute([$row['campaign_id']]);$company=$campaign->fetch();$account->execute([$company['company_id']]);$wa=$account->fetch();if(!$wa)throw new RuntimeException('Nenhum número Meta configurado.');$client=new MetaClient(ConectaFlow\Security::decrypt($wa['access_token_encrypted']),Config::get('META_GRAPH_VERSION','v20.0'));$result=$client->post($wa['phone_number_id'].'/messages',['messaging_product'=>'whatsapp','to'=>$row['phone'],'type'=>'text','text'=>['body'=>str_replace(['{{nome}}','{{telefone}}'],[$row['name'],$row['phone']],$row['message_text'])]]);$provider=$result['messages'][0]['id']??null;Database::transaction(function($pdo)use($row,$provider){$pdo->prepare('UPDATE message_queue SET status="done" WHERE id=?')->execute([$row['id']]);$pdo->prepare('UPDATE campaign_contacts SET status="sent",provider_message_id=?,sent_at=NOW() WHERE id=?')->execute([$provider,$row['campaign_contact_id']]);$pdo->prepare('INSERT INTO messages(company_id,contact_id,campaign_id,direction,body,provider_message_id,status) VALUES((SELECT company_id FROM campaigns WHERE id=?),?,? ,"outbound",?,?,"sent")')->execute([$row['campaign_id'],$row['contact_id'],$row['campaign_id'],$row['message_text'],$provider]);$pdo->prepare('UPDATE campaigns SET sent_count=sent_count+1 WHERE id=?')->execute([$row['campaign_id']]);});}catch(Throwable $e){$retry=((int)$row['attempts'])<$maxRetries;db()->prepare('UPDATE message_queue SET status=?,last_error=?,available_at=DATE_ADD(NOW(),INTERVAL 5 MINUTE) WHERE id=?')->execute([$retry?'pending':'failed',substr($e->getMessage(),0,500),$row['id']]);db()->prepare('UPDATE campaign_contacts SET status="failed",last_error=? WHERE id=?')->execute([substr($e->getMessage(),0,500),$row['campaign_contact_id']]);db()->prepare('UPDATE campaigns SET failed_count=failed_count+1 WHERE id=?')->execute([$row['campaign_id']]);}}
    if(!$once && !$rows) sleep(3);
} while(!$once);
